import json,glob,os,datetime,statistics,collections
rows=[]
for f in sorted(glob.glob('.suspense/history/*.json'),key=os.path.getmtime)[-40:]:
    try: d=json.load(open(f))
    except: continue
    out=d.get('output',[]); ctx=[]; sid=None
    for e in out:
        if not isinstance(e,dict): continue
        if e.get('type')=='system' and e.get('subtype')=='init': sid=e.get('session_id')
        ev=e.get('event') if e.get('type')=='stream_event' else None
        if ev and ev.get('type')=='message_start' and not e.get('parent_tool_use_id'):
            u=ev['message'].get('usage',{})
            ctx.append(u.get('input_tokens',0)+u.get('cache_read_input_tokens',0)+u.get('cache_creation_input_tokens',0))
    res=[e for e in out if isinstance(e,dict) and e.get('type')=='result']
    if not res: continue
    r=res[-1]
    pi=open(f[:-5]+'.pi').read() if os.path.exists(f[:-5]+'.pi') else ''
    mode='?'
    for line in pi.splitlines():
        if line.strip().startswith('mode:'): mode=line.split(':')[1].strip()
    rows.append((os.path.getmtime(f),mode,r.get('duration_ms',0)/1000,r.get('num_turns'),ctx[0] if ctx else 0,ctx[-1] if ctx else 0,str(sid)[:8],round(r.get('total_cost_usd') or 0,2)))
for t,mode,dur,turns,c0,c1,sid,cost in rows[-14:]:
    print(f"{datetime.datetime.fromtimestamp(t):%m-%d %H:%M} {mode:9} {dur:6.0f}s turns {turns:3} ctx {c0/1000:6.0f}k→{c1/1000:6.0f}k  sess {sid} ${cost}")
by=collections.defaultdict(list)
for t,mode,dur,turns,c0,c1,sid,cost in rows: by[mode].append((dur,c0,cost))
for m,v in by.items():
    print(f"{m}: n={len(v)} median {statistics.median(x[0] for x in v):.0f}s start-ctx {statistics.median(x[1] for x in v)/1000:.0f}k cost ${statistics.median(x[2] for x in v):.2f}")
