import json,collections,os
p=os.path.expanduser('~/.claude/projects/-home-hyphyphyph-piton-repl/827f0178-'.replace('827f0178-','')) 
import glob
f=[x for x in glob.glob(os.path.expanduser('~/.claude/projects/-home-hyphyphyph-piton-repl/827f0178*.jsonl'))]
print(f, os.path.getsize(f[0])//1024,'KB' if f else '')
L=[json.loads(l) for l in open(f[0])]
b=[i for i,e in enumerate(L) if e.get('type')=='system' and 'compact' in (e.get('subtype') or '')]
live=L[b[-1]:] if b else L
tn={}; by=collections.Counter()
for e in live:
    c=(e.get('message') or {}).get('content')
