        elif t=='tool_result': by['tool_result:'+tn.get(x.get('tool_use_id'),'?')]+=len(json.dumps(x.get('content')))
        elif t=='text': by[e.get('type')+':text']+=len(x.get('text',''))
        elif t=='thinking': by['thinking']+=len(x.get('thinking',''))
tot=sum(by.values()); print('entries',len(L),'compactions',len(b),'live chars',f'{tot:,}')
for k,v in by.most_common(8): print(f'{v/tot*100:5.1f}% {v:>10,} {k}')
